CREATE TABLE "news"."news_references" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "news_id" uuid NOT NULL, "order" integer NOT NULL DEFAULT 0, "kind" text NOT NULL, "article_id" text, "label" text, "url" text, "intro" text, PRIMARY KEY ("id"), FOREIGN KEY ("news_id") REFERENCES "news"."news"("id") ON UPDATE cascade ON DELETE cascade, FOREIGN KEY ("article_id") REFERENCES "public"."legi_articles"("id") ON UPDATE restrict ON DELETE restrict, UNIQUE ("news_id", "article_id"), CONSTRAINT "news_references_kind_check" CHECK (("kind" = 'legi' AND "article_id" IS NOT NULL AND "label" IS NULL AND "url" IS NULL) OR ("kind" = 'external' AND "article_id" IS NULL AND "label" IS NOT NULL AND "url" IS NOT NULL)));
COMMENT ON TABLE "news"."news_references" IS E'Références des actualités : articles du code du travail et liens externes';
